lessons.solution_code:
#include <vector>
#include <algorithm>

inline void sortVector(std::vector<int>& vec) {
    std::sort(vec.begin(), vec.end());
}

tests.unittest_code:
std::vector<int> v = {3, 1, 2};
sortVector(v);
if (v[0] != 1 || v[2] != 3) throw std::runtime_error("Sort failed");

